import type { Column, Typed } from '../Column'

type JsonColumnType<Type extends string = string, Default extends Type = Type> = Column<Type, Default>

type NameValuePairsColumnType<Type extends string = string, Default extends Type = Type> = Column<Type, Default>

/**
 * A Column for a JSON type field.
 * Accepts string values (use json() helper for objects).
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *
 * @example
 * ```typescript
 * const config = JsonColumn({
 *     label: 'Configuration',
 *     default: json({ theme: 'dark', language: 'en' }),
 * })
 * ```
 */
export function JsonColumn<
    const Type extends string = string,
    const Default extends Type = Type,
    const C extends JsonColumnType<Type, Default> = JsonColumnType<Type, Default>,
>(config: C & JsonColumnType<Type, Default>) {
    return config as Typed<Type, C>
}

/**
 * A Column for a name-value pairs field.
 * Stores flat key-value pair data (no nested objects).
 * Accepts string values (use nameValuePairs() helper for objects).
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *
 * @example
 * ```typescript
 * const metadata = NameValuePairsColumn({
 *     label: 'Metadata',
 *     default: nameValuePairs({ owner: 'admin', version: '1.0' }),
 * })
 * ```
 */
export function NameValuePairsColumn<
    const Type extends string = string,
    const Default extends Type = Type,
    const C extends NameValuePairsColumnType<Type, Default> = NameValuePairsColumnType<Type, Default>,
>(config: C & NameValuePairsColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
